import java.util.*;
public class Main {
    static int solve(int n, int[] memo) {
        if (n <= 2) {
            return n;
        }
        if (memo[n] != -1) {
            return memo[n];
        }
        memo[n] = solve(n - 1, memo) + solve(n - 2, memo);
        return memo[n];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n <= 2) {
            System.out.println(n);
            sc.close();
            return;
        }
        int[] memo = new int[n + 1];
        Arrays.fill(memo, -1);
        memo[1] = 1;
        memo[2] = 2;
        System.out.println(solve(n, memo));
        sc.close();
    }
}

